#!/usr/bin/env node
// Guards the `js_wasm32` backend against drift:
//
//   1. no `webgpu_*` wrapper may still be `unimplemented(...)`
//   2. every procedure declared in `foreign webgpu { ... }` must have an
//      implementation in `wasm/webgpu.js` (explicit or generated by a
//      manager `interface()` spread)
//
// Usage: node tools/check_js_backend.mjs

import fs from 'node:fs';
import path from 'node:path';
import process from 'node:process';

const ROOT = path.resolve(import.meta.dirname, '..');
const ODIN = path.join(ROOT, 'gpu', 'webgpu.odin');
const SHIM = path.join(ROOT, 'wasm', 'webgpu.js');

const odin = fs.readFileSync(ODIN, 'utf8');
const shim = fs.readFileSync(SHIM, 'utf8');

const failures = [];

// 1. Unimplemented wrappers -------------------------------------------------
{
	const lines = odin.split(/\r?\n/);
	let current = null;
	for (const line of lines) {
		const start = /^(webgpu_\w+) :: proc/.exec(line);
		if (start) {
			current = start[1];
			continue;
		}
		if (current && /\bunimplemented\(/.test(line)) {
			failures.push(`unimplemented wrapper: ${current}`);
			current = null;
		} else if (current && line === '}') {
			current = null;
		}
	}
}

// 2. Foreign declarations without a shim implementation ---------------------
{
	// Names the shim builds at runtime: `${manager}AddRef|Release|SetLabel`.
	const managers = [...shim.matchAll(/this\.(\w+) = new WebGPU\w+Manager\('(\w+)'/g)].map((m) => ({
		field: m[1],
		name: m[2],
	}));
	const generated = new Set();
	for (const spread of shim.matchAll(/\.\.\.this\.(\w+)\.interface\((true|false)?\)/g)) {
		const manager = managers.find((m) => m.field === spread[1]);
		if (!manager) continue;
		generated.add(`webgpu${manager.name}AddRef`);
		generated.add(`webgpu${manager.name}Release`);
		if (spread[2] === 'true') generated.add(`webgpu${manager.name}SetLabel`);
	}

	const explicit = new Set(
		[...shim.matchAll(/^\s{8}(webgpu[A-Za-z0-9_]+):/gm)].map((m) => m[1]),
	);

	// Procedure declarations inside the foreign block only.
	const foreignBlock = /foreign webgpu \{([\s\S]*?)\n\s*\}\n/.exec(odin)?.[1] ?? '';
	const declared = [...foreignBlock.matchAll(/^\s{4}(webgpu[A-Za-z0-9_]+) :: proc/gm)].map((m) => m[1]);

	for (const name of declared) {
		if (!explicit.has(name) && !generated.has(name)) {
			failures.push(`no shim implementation: ${name}`);
		}
	}
}

// 3. ENUMS table cardinality and sentinel placement -------------------------
//
// `odinEnumValue` converts in both directions using the array index as the
// ordinal, so an entry inserted or dropped anywhere shifts every value after it.
// A leading sentinel (`undefined`/`null`) is correct only when the Odin enum's
// ordinal 0 means "not provided"; everywhere else ordinal 0 is a real value.
{
	/** JS table name -> [Odin enum name, first entry is a sentinel, allow shorter] */
	const TABLES = {
		PrimitiveTopology: ['Primitive_Topology', false],
		IndexFormat: ['Index_Format', true],
		FrontFace: ['Front_Face', false],
		CullMode: ['Cull_Mode', false],
		PolygonMode: ['Polygon_Mode', false],
		VertexStepMode: ['Vertex_Step_Mode', false],
		CompareFunction: ['Compare_Function', true],
		BlendOperation: ['Blend_Operation', false],
		BlendFactor: ['Blend_Factor', true],
		LoadOp: ['Load_Op', true],
		StoreOp: ['Store_Op', true],
		StencilOperation: ['Stencil_Operation', false],
		TextureAspect: ['Texture_Aspect', false],
		TextureViewDimension: ['Texture_View_Dimension', true],
		AddressMode: ['Address_Mode', false],
		FilterMode: ['Filter_Mode', false],
		MipmapFilterMode: ['Mipmap_Filter_Mode', false],
		TextureFormat: ['Texture_Format', true],
		VertexFormat: ['Vertex_Format', false],
		// WebGPU exposes fewer features than the native WebGPU implementation; the table is a prefix of
		// the Odin enum, so ordinals below its length still line up.
		FeatureName: ['Feature_Name', false, true],
		InstanceFeatureName: ['Instance_Feature_Name', false],
		BufferBindingType: ['Buffer_Binding_Type', true],
		SamplerBindingType: ['Sampler_Binding_Type', true],
		TextureSampleType: ['Texture_Sample_Type', true],
		StorageTextureAccess: ['Storage_Texture_Access', true],
		QueryType: ['Query_Type', false],
		TextureDimension: ['Texture_Dimension', true],
		ErrorType: ['Error_Type', false],
		ErrorFilter: ['Error_Filter', false],
		WGSLLanguageFeatureName: ['WGSL_Language_Feature_Name', false],
		PowerPreference: ['Power_Preference', true],
		CompositeAlphaMode: ['Composite_Alpha_Mode', false],
		PresentMode: ['Present_Mode', false],
		DeviceLostReason: ['Device_Lost_Reason', false],
		BufferMapState: ['Buffer_Map_State', false],
		ComponentSwizzle: ['Component_Swizzle', true],
		PredefinedColorSpace: ['Predefined_Color_Space', false],
		ToneMappingMode: ['Tone_Mapping_Mode', false],
		FeatureLevel: ['Feature_Level', false],
		BackendType: ['Backend_Type', true],
		AdapterType: ['Device_Type', false],
		MapAsyncStatus: ['Map_Async_Status', false],
		CreatePipelineAsyncStatus: ['Create_Pipeline_Async_Status', false],
		PopErrorScopeStatus: ['Pop_Error_Scope_Status', false],
		QueueWorkDoneStatus: ['Queue_Work_Done_Status', false],
		CompilationInfoRequestStatus: ['Compilation_Info_Request_Status', false],
		WaitStatus: ['Wait_Status', false],
		SurfaceGetCurrentTextureStatus: ['Surface_Get_Current_Texture_Status', false],
	};

	const odinEnums = new Map();
	for (const file of fs.readdirSync(path.join(ROOT, 'gpu')).filter((f) => f.endsWith('.odin'))) {
		const text = fs.readFileSync(path.join(ROOT, 'gpu', file), 'utf8');
		for (const match of text.matchAll(/^(\w+)\s*::\s*enum\s+i32\s*\{([\s\S]*?)^\}/gm)) {
			const members = match[2]
				.replace(/\/\/[^\n]*/g, '')
				.split(/\r?\n/)
				.map((line) => line.trim())
				.filter((line) => /^[A-Za-z_]\w*/.test(line));
			odinEnums.set(match[1], members.length);
		}
	}

	const enumBodyStart = shim.indexOf('const ENUMS = {');
	const enumBodyOpen = shim.indexOf('{', enumBodyStart) + 1;
	let depth = 1;
	let cursor = enumBodyOpen;
	while (depth > 0 && cursor < shim.length) {
		if (shim[cursor] === '{') depth += 1;
		else if (shim[cursor] === '}') depth -= 1;
		cursor += 1;
	}
	const enumBody = shim.slice(enumBodyOpen, cursor - 1);

	const splitTopLevel = (source) => {
		const parts = [];
		let current = '';
		let nesting = 0;
		let quote = null;
		for (const char of source) {
			if (quote) {
				current += char;
				if (char === quote) quote = null;
				continue;
			}
			if (char === "'" || char === '"') {
				quote = char;
				current += char;
			} else if ('[{('.includes(char)) {
				nesting += 1;
				current += char;
			} else if (']})'.includes(char)) {
				nesting -= 1;
				current += char;
			} else if (char === ',' && nesting === 0) {
				parts.push(current.trim());
				current = '';
			} else {
				current += char;
			}
		}
		if (current.trim() !== '') parts.push(current.trim());
		return parts;
	};

	const tables = new Map();
	for (const match of enumBody.matchAll(/^\s*([A-Za-z_]\w*)\s*:\s*\[/gm)) {
		const open = enumBody.indexOf('[', match.index);
		let bracketDepth = 0;
		let end = open;
		while (end < enumBody.length) {
			if (enumBody[end] === '[') bracketDepth += 1;
			else if (enumBody[end] === ']') {
				bracketDepth -= 1;
				if (bracketDepth === 0) break;
			}
			end += 1;
		}
		tables.set(match[1], splitTopLevel(enumBody.slice(open + 1, end)));
	}

	for (const [tableName, [odinName, sentinel, allowShorter]] of Object.entries(TABLES)) {
		const entries = tables.get(tableName);
		const odinCount = odinEnums.get(odinName);

		if (!entries) {
			failures.push(`missing ENUMS table: ${tableName}`);
			continue;
		}
		if (odinCount === undefined) {
			failures.push(`missing Odin enum for ${tableName}: ${odinName}`);
			continue;
		}

		const first = entries[0];
		const hasSentinel = first === 'undefined' || first === 'null';
		if (hasSentinel !== sentinel) {
			failures.push(
				`${tableName}: ordinal 0 ${sentinel ? 'must be a sentinel' : 'is a real value'}`,
			);
		}

		if (allowShorter ? entries.length > odinCount : entries.length !== odinCount) {
			failures.push(
				`${tableName}: ${entries.length} entries, ${odinName} has ${odinCount}`,
			);
		}
	}
}

// 4. Packed Handle managers must be read with `getPacked` -------------------
//
// Odin passes a `distinct Handle` by pointer, so the argument is the address of
// a `gpu.Handle`, not a packed handle. `WebGPUObjectManager` (instances,
// adapters, devices, surfaces) intentionally uses `get`, but every
// `WebGPUHandleManager` must go through `getPacked`.
{
	const handleManagers = [
		...shim.matchAll(/this\.(\w+) = new WebGPUHandleManager\(/g),
	].map((match) => match[1]);

	for (const field of handleManagers) {
		if (new RegExp(`this\\.${field}\\.get\\(`).test(shim)) {
			failures.push(`this.${field}.get(...) on a packed Handle manager; use getPacked`);
		}
	}
}

if (failures.length > 0) {
	console.error(`${failures.length} js backend problem(s):`);
	for (const failure of failures) console.error(`  ${failure}`);
	process.exit(1);
}

console.log(
	'js backend ok: no unimplemented wrappers, every foreign proc has a shim implementation, every ENUMS table matches its Odin enum',
);
